SELECT DATE_FORMAT(shipped_date, 'yyyy-MM') AS shipped_month, DATE_TRUNC('MONTH', delivered_date) AS delivered_month, COUNT(DISTINCT cost) AS unique_orders, ROUND((100 * SUM(CASE WHEN carrier = 'Flash' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_flash FROM shipments GROUP BY DATE_FORMAT(shipped_date, 'yyyy-MM'), DATE_TRUNC('MONTH', delivered_date) ORDER BY unique_orders DESC, delivered_month DESC;
